  1	/**
  2	 * scripts/lib/persona-model-resolution.js
  3	 *
  4	 * Model resolution helpers for the personas name-mapping build pass.
  5	 *
  6	 * Provides:
  7	 *   loadModelRegistry(registryDir)  — reads local.json / default.json + assignments.json
  8	 *   resolveModel(...)               — resolves model fields using the priority chain
  9	 *
 10	 * Both functions are pure (no side-effects beyond the file reads performed by
 11	 * loadModelRegistry), making them straightforwardly unit-testable.
 12	 *
 13	 * Priority chain for resolveModel:
 14	 *   1. assignments.json persona_models[personaId]  (skip when resolved slug === "inherit")
 15	 *   2. per-persona YAML model_slug                 (skip when value === "inherit")
 16	 *   3. assignments.json default_model_uuid          (skip when resolved slug === "inherit")
 17	 *   4. _shared.yaml default_model_slug
 18	 *   5. "inherit" sentinel fallback
 19	 */
 20	
 21	import fs from 'fs';
 22	import path from 'path';
 23	
 24	// ---------------------------------------------------------------------------
 25	// loadModelRegistry
 26	// ---------------------------------------------------------------------------
 27	
 28	/**
 29	 * Load the model registry files from `registryDir`.
 30	 *
 31	 * Reads `local.json` (falling back to `default.json`) to build the UUID → slug
 32	 * map, and reads `assignments.json` when present.
 33	 *
 34	 * @param {string} registryDir  Absolute path to the model-registry directory.
 35	 * @param {{ warn?: (msg: string) => void }} [opts]
 36	 *   Optional overrides — `warn` defaults to `console.warn`.
 37	 * @returns {{ uuidToSlug: Map<string,string>, registryEntries: object[], assignments: object|null }}
 38	 */
 39	export function loadModelRegistry(registryDir, opts = {}) {
 40	  const warn = opts.warn ?? ((msg) => console.warn(msg));
 41	
 42	  const localJsonPath   = path.join(registryDir, 'local.json');
 43	  const defaultJsonPath = path.join(registryDir, 'default.json');
 44	  const assignmentsPath = path.join(registryDir, 'assignments.json');
 45	
 46	  // Build UUID → slug map from local.json (seed from default.json if absent)
 47	  const uuidToSlug     = new Map();
 48	  let   registryEntries = [];
 49	
 50	  const regPath = fs.existsSync(localJsonPath) ? localJsonPath : defaultJsonPath;
 51	  if (fs.existsSync(regPath)) {
 52	    try {
 53	      const parsed = JSON.parse(fs.readFileSync(regPath, 'utf8'));
 54	      if (Array.isArray(parsed)) {
 55	        registryEntries = parsed;
 56	        for (const entry of parsed) {
 57	          if (entry && typeof entry.id === 'string' && typeof entry.slug === 'string') {
 58	            uuidToSlug.set(entry.id, entry.slug);
 59	          }
 60	        }
 61	      }
 62	    } catch (e) {
 63	      warn(`[WARN] build-personas: failed to parse model registry at ${regPath}: ${e.message}`);
 64	    }
 65	  }
 66	
 67	  // Load assignments.json (optional — absent in clean installs)
 68	  let assignments = null;
 69	  if (fs.existsSync(assignmentsPath)) {
 70	    try {
 71	      const raw = JSON.parse(fs.readFileSync(assignmentsPath, 'utf8'));
 72	      if (raw && typeof raw === 'object') {
 73	        assignments = raw;
 74	      }
 75	    } catch (e) {
 76	      warn(`[WARN] build-personas: failed to parse assignments.json: ${e.message}`);
 77	    }
 78	  }
 79	
 80	  return { uuidToSlug, registryEntries, assignments };
 81	}
 82	
 83	// ---------------------------------------------------------------------------
 84	// resolveModel
 85	// ---------------------------------------------------------------------------
 86	
 87	/**
 88	 * Resolve display name, slug, and cc_model for a persona.
 89	 *
 90	 * Priority chain (mirrors the build plugin + orchestrator):
 91	 *   1. assignments.json persona_models[personaId]  (skip if resolved slug === "inherit")
 92	 *   2. yamlModelSlug                               (skip if value === "inherit")
 93	 *   3. assignments.json default_model_uuid          (skip if resolved slug === "inherit")
 94	 *   4. sharedModelSlug / sharedModelName
 95	 *   5. "inherit" sentinel — { model: "Inherit / Auto", model_slug: "inherit", cc_model: "inherit" }
 96	 *
 97	 * @param {string|undefined}       personaId       Persona ID (used as assignments key).
 98	 * @param {string|undefined}       yamlModelSlug   Per-persona model_slug from YAML.
 99	 * @param {string|undefined}       sharedModelSlug Shared default model slug (_shared.yaml).
100	 * @param {string|undefined}       sharedModelName Shared default model name (_shared.yaml).

101	  });
102	
103	  // AC-7, chain step 3: default_model_uuid used when no persona assignment and no YAML slug
104	  it('returns the default assignment slug when no per-persona assignment or YAML slug (priority 3)', () => {
105	    const assignments = {
106	      default_model_uuid: '00000000-0000-0000-0000-000000000003', // Gemini
107	      persona_models: {},
108	    };
109	
110	    const result = resolveModel(
111	      'my-persona-id',
112	      undefined,         // no per-persona YAML slug
113	      'claude-opus-4-6', // shared default — should be ignored (assignment takes priority)
114	      'Claude Opus 4.6',
115	      buildUuidToSlug(),
116	      assignments,
117	      REGISTRY_ENTRIES,
118	    );
119	
120	    expect(result).toEqual({
121	      model:      'Gemini 3.5 Flash',
122	      model_slug: 'gemini-3-5-flash',
123	      cc_model:   'gemini-3-5-flash',
124	    });
125	  });
126	
127	  // AC-7, chain step 4: _shared.yaml default used when no assignments and no YAML slug
128	  it('falls back to _shared.yaml default model slug (priority 4)', () => {
129	    const result = resolveModel(
130	      'my-persona-id',
131	      undefined,             // no per-persona YAML slug
132	      'claude-sonnet-4-6',   // shared default slug
133	      'Claude Sonnet 4.6',
134	      buildUuidToSlug(),
135	      null,                  // no assignments
136	      REGISTRY_ENTRIES,
137	    );
138	
139	    expect(result).toEqual({
140	      model:      'Claude Sonnet 4.6',
141	      model_slug: 'claude-sonnet-4-6',
142	      cc_model:   'inherit',
143	    });
144	  });
145	
146	  // AC-5: no model configured → inherit sentinel
147	  it('returns the inherit sentinel when no model is configured anywhere (priority 5)', () => {
148	    const result = resolveModel(
149	      'my-persona-id',
150	      undefined,   // no per-persona YAML slug
151	      undefined,   // no shared default
152	      undefined,
153	      new Map(),   // empty UUID map
154	      null,        // no assignments
155	      [],          // empty registry
156	    );
157	
158	    expect(result).toEqual({
159	      model:      'Inherit / Auto',
160	      model_slug: 'inherit',
161	      cc_model:   'inherit',
162	    });
163	  });
164	
165	  // AC-2 (from WP-004, mirrored here for the name-mapping): per-persona assignment
166	  // with "inherit" slug → skip and fall back to next level
