  9	import fs from 'fs';
 10	import path from 'path';
 11	import { execFileSync } from 'child_process';
 12	import { createRequire } from 'module';
 13	import { loadModelRegistry, resolveModel } from './lib/persona-model-resolution.js';
 14	
 15	const _require = createRequire(import.meta.url);
 16	
 17	const ROOT     = path.join(import.meta.dirname, '..');
 18	const PERSONAS = path.join(ROOT, 'personas');
 19	const CONFIG   = path.join(PERSONAS, 'persona-build.config.js');
 20	const CLI      = path.join(PERSONAS, 'node_modules', '@mistralys', 'persona-builder', 'dist', 'cli.js');
 21	
 22	// --dry-run is accepted as a convenience alias for --check (same behaviour)
 23	const CHECK  = process.argv.includes('--check') || process.argv.includes('--dry-run');
 24	const STRICT = process.argv.includes('--strict');
 25	
 26	// Pre-build: clean output directories so stale/renamed files don't linger.
 27	// Skipped in --check / --dry-run mode (read-only).
 28	if (!CHECK) {
 29	  const config = _require(CONFIG);
 30	  const outputDirs = [];
 31	  for (const suite of Object.values(config.suites)) {
 32	    if (suite.outVscode)     outputDirs.push(suite.outVscode);
 33	    if (suite.outClaudeCode) outputDirs.push(suite.outClaudeCode);
 34	    if (suite.outputDirs) {
 35	      for (const dir of Object.values(suite.outputDirs)) {
 36	        outputDirs.push(dir);
 37	      }
 38	    }
 39	  }
 40	  for (const dir of outputDirs) {
 41	    if (!fs.existsSync(dir)) continue;
 42	    const files = fs.readdirSync(dir).filter(f => f.endsWith('.md'));
 43	    for (const file of files) {
 44	      fs.unlinkSync(path.join(dir, file));
 45	    }
 46	  }
 47	}
 48	
 49	// Delegate build to the library CLI
 50	const cliArgs = ['--config', CONFIG];
 51	if (CHECK)  cliArgs.push('--check');
 52	if (STRICT) cliArgs.push('--strict');
 53	
 54	try {
 55	  execFileSync(process.execPath, [CLI, ...cliArgs], { stdio: 'inherit' });
 56	} catch (err) {
