 60	// Post-build: sync personas/package.json version from changelog (real builds only)
 61	if (!CHECK) {
 62	  const changelogPath = path.join(ROOT, 'personas', 'changelog.md');
 63	  const pkgPath       = path.join(ROOT, 'personas', 'package.json');
 64	  const changelog     = fs.readFileSync(changelogPath, 'utf8');
 65	  const match         = changelog.match(/^## v(\d+\.\d+\.\d+)/m);
 66	
 67	  if (!match) {
 68	    console.warn('[WARN] Could not extract version from personas/changelog.md — skipping package.json update.');
 69	  } else {
 70	    const newVersion = match[1];
 71	    const pkg        = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
 72	    if (pkg.version !== newVersion) {
 73	      const oldVersion = pkg.version;
 74	      pkg.version = newVersion;
 75	      fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n', 'utf8');
 76	      console.log(`Updated personas/package.json: ${oldVersion} → ${newVersion}`);
 77	    } else {
