105	  const SCALAR_FIELDS = ['number', 'role', 'id', 'version', 'vs_file_name', 'cc_file_name', 'da_file_name'];
106	
107	  // Non-ledger personas use the same scalar fields minus number/role (which are
108	  // absent or derived differently).
109	  const STANDALONE_SCALAR_FIELDS = ['id', 'name', 'version', 'vs_file_name', 'cc_file_name', 'da_file_name', 'model_slug'];
110	
111	  // ---------------------------------------------------------------------------
112	  // Load model registry once for the entire name-mapping pass
113	  // (loadModelRegistry and resolveModel are imported from lib/persona-model-resolution.js)
114	  // ---------------------------------------------------------------------------
115	
116	  const registryDir = path.join(ROOT, 'personas', 'model-registry');
117	  const { uuidToSlug, registryEntries, assignments } = loadModelRegistry(registryDir);
118	
119	  /**
120	   * Extracts simple scalar (string/number) fields from a YAML file without
121	   * external dependencies. Only top-level key: value lines are parsed; nested
122	   * structures and lists are ignored.
123	   */
124	  function parseYamlScalars(text, fields) {
125	
126	    const result = {};
127	    for (const line of text.split(/\r?\n/)) {
128	      const m = line.match(/^([a-zA-Z_][a-zA-Z0-9_]*)\s*:\s*(.+)$/);
129	      if (!m) continue;
130	      const key = m[1];
131	      if (!fields.includes(key)) continue;
132	      let val = m[2].trim();
133	      // Strip surrounding single or double quotes (handles `"value"` and `'value'`).
134	      // Also handles quoted values followed by a trailing inline comment:
135	      //   `key: "value"   # comment` → first match the closing quote, strip comment, then unquote.
136	      if (val.startsWith('"') || val.startsWith("'")) {
137	        const q = val[0];
138	        // Find the closing quote; content between quotes may contain any char.
139	        const closeIdx = val.indexOf(q, 1);
140	        if (closeIdx !== -1) {
141	          val = val.slice(1, closeIdx);
142	        } else {
143	          // Unclosed quote — fall back to comment-strip and trim
144	          val = val.replace(/\s+#.*$/, '').trim();
145	        }
146	      } else {
147	        // Unquoted scalar: strip trailing inline YAML comment
148	        // e.g. `role: Developer # note` → `Developer`
149	        val = val.replace(/\s+#.*$/, '').trim();
150	      }
151	      result[key] = val;
152	    }
153	    return result;
154	  }
155	
156	  /**
157	   * Extracts the string content of a YAML block scalar (`key: |` or `key: |-`)
158	   * from raw YAML text without a full YAML parse.
159	   * Returns the block content (newline-joined, trimmed) or undefined when the
160	   * key is absent or does not use a block scalar indicator.
161	   */
162	  function extractYamlBlockScalar(text, key) {
163	    const escaped = key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
164	    const re    = new RegExp(`^${escaped}\\s*:\\s*\\|[-+]?\\s*$`, 'm');
165	    const match = re.exec(text);
166	    if (!match) return undefined;
167	
168	    const after   = text.slice(match.index + match[0].length);
169	    const lines   = after.split(/\r?\n/);
170	    let   indent  = -1;
171	    const content = [];
172	
173	    for (const line of lines) {
174	      if (line.trim() === '') {
175	        if (indent !== -1) content.push('');
176	        continue;
177	      }
178	      const m          = line.match(/^(\s+)/);
179	      const lineIndent = m ? m[1].length : 0;
180	      if (lineIndent === 0) break;            // outdented — end of block scalar
181	      if (indent === -1) indent = lineIndent; // first content line determines indent
182	      if (lineIndent < indent) break;
183	      content.push(line.slice(indent));
184	    }
185	
186	    const joined = content.join('\n').trimEnd();
187	    return joined || undefined;
188	  }
189	
190	  /**
191	   * Extracts the version string from a `changelog: |` block scalar in raw YAML
192	   * text. Returns the version string (e.g. "3.6.3") or undefined when absent.
193	   *
194	   * Regex patterns mirror resolveChangelogMeta() in @mistralys/persona-builder:
195	   *   Primary:  "3.6.3 (2026-05-29): description"
196	   *   Fallback: "3.6.3: description"            (no date)
197	   */
198	  function resolveVersionFromChangelog(text) {
199	    if (typeof text !== 'string') return undefined;
200	    const content = extractYamlBlockScalar(text, 'changelog');
201	    if (!content) return undefined;
202	    // Line-by-line first-wins, mirrors resolveChangelogMeta() in the library
203	    for (const line of content.split(/\r?\n/)) {
204	      const withDate = line.match(/^(\d+\.\d+\.\d+)\s*\(\d{4}-\d{2}-\d{2}\)\s*:/);
205	      if (withDate) return withDate[1];
206	      const withoutDate = line.match(/^(\d+\.\d+\.\d+)\s*:/);
207	      if (withoutDate) return withoutDate[1];
208	    }
209	    return undefined;
210	  }
211	
212	  /**
213	   * Validates the `changelog` field in a persona YAML.
214	   * Warns when the field is present but unparseable, or when the first version
215	   * entry has no date. Logs an info message when explicit `version` or
216	   * `last_updated` scalar fields coexist with the changelog (indicating they
217	   * can be removed).
218	   */
219	  function validateChangelogField(raw, filename) {
220	    const content = extractYamlBlockScalar(raw, 'changelog');
221	    if (content === undefined) return;
222	
223	    // Track first-entry date status and detect same-version/different-date duplicates.
224	    let firstHasDate = null; // null = not yet seen, true/false = first entry result
225	    let firstVersion = null;
226	    const versionDates = {}; // version → date string (first occurrence)
227	
228	    for (const line of content.split(/\r?\n/)) {
229	      const withDate = line.match(/^(\d+\.\d+\.\d+)\s*\((\d{4}-\d{2}-\d{2})\)\s*:/);
230	      if (withDate) {
231	        const [, ver, date] = withDate;
232	        if (firstHasDate === null) { firstHasDate = true; firstVersion = ver; }
233	        if (Object.prototype.hasOwnProperty.call(versionDates, ver)) {
234	          if (versionDates[ver] !== date) {
235	            console.warn(`[WARN] ${filename}: version "${ver}" appears with two different dates` +
236	              ` (${versionDates[ver]} and ${date}).`);
237	          }
238	        } else {
239	          versionDates[ver] = date;
240	        }
241	        continue;
242	      }
243	      const withoutDate = line.match(/^(\d+\.\d+\.\d+)\s*:/);
244	      if (withoutDate && firstHasDate === null) { firstHasDate = false; firstVersion = withoutDate[1]; }
245	    }
246	
247	    if (firstHasDate === null) {
248	      console.warn(`[WARN] ${filename}: changelog present but no parseable version found.`);
249	    } else if (!firstHasDate) {
250	      console.warn(`[WARN] ${filename}: changelog first entry has no date (version "${firstVersion}").`);
251	    }
252	
253	    const scalars = parseYamlScalars(raw, ['version', 'last_updated']);
254	    if (scalars.version) {
255	      console.info(`[INFO] ${filename}: explicit version "${scalars.version}" coexists with changelog.`);
256	    }
257	    if (scalars.last_updated) {
258	      console.info(`[INFO] ${filename}: explicit last_updated "${scalars.last_updated}" coexists with changelog.`);
259	    }
260	  }
261	
262	  /** Returns the filename stem (strips the last extension). */
263	  function stem(filename) {
264	    return filename.replace(/\.[^.]+$/, '');
265	  }
266	
267	  // ---------------------------------------------------------------------------
268	  // Ledger suite — read _shared.yaml for default_version and default model info
269	  // ---------------------------------------------------------------------------
270	
271	  const ledgerSharedRaw   = fs.readFileSync(path.join(ledgerMetaDir, '_shared.yaml'), 'utf8');
272	  const ledgerSharedData  = parseYamlScalars(ledgerSharedRaw, ['default_version', 'default_model', 'default_model_slug']);
273	  const DEFAULT_VERSION   = ledgerSharedData.default_version;
274	  const LEDGER_DEFAULT_MODEL      = ledgerSharedData.default_model;
275	  const LEDGER_DEFAULT_MODEL_SLUG = ledgerSharedData.default_model_slug;
276	
277	  // ---------------------------------------------------------------------------
278	  // Build ledger entries
279	  // ---------------------------------------------------------------------------
280	
281	  const ledgerEntries = LEDGER_PERSONA_FILES.map(file => {
282	    const raw  = fs.readFileSync(path.join(ledgerMetaDir, file), 'utf8');
283	    const data = parseYamlScalars(raw, SCALAR_FIELDS);
284	
285	    validateChangelogField(raw, file);
286	
287	    const ccFileName = data.cc_file_name;
288	    const daFileName = data.da_file_name || ccFileName;
289	    const ccStem     = stem(ccFileName);
290	    const daStem     = stem(daFileName);
291	    const number     = Number(data.number);
292	    const version    = resolveVersionFromChangelog(raw) || data.version || DEFAULT_VERSION;
293	
294	    const modelInfo = resolveModel(
295	      data.id,
296	      undefined, // ledger personas don't carry per-persona model_slug in YAML (uses shared default)
297	      LEDGER_DEFAULT_MODEL_SLUG,
298	      LEDGER_DEFAULT_MODEL,
299	      uuidToSlug,
300	      assignments,

301	      registryEntries,
302	    );
303	
304	    return {
305	      number,
306	      id:         data.id,
307	      role:       data.role,
308	      version,
309	      suite:      'ledger',
310	      model:      modelInfo.model,
311	      model_slug: modelInfo.model_slug,
312	      cc_model:   modelInfo.cc_model,
313	      vscode: {
314	        file_name:  data.vs_file_name,
315	        agent_name: `${number} - ${data.role} v${version}`,
316	      },
317	      claude_code: {
318	        file_name:  ccFileName,
319	        agent_name: ccStem,
320	      },
321	      deep_agents: {
322	        file_name:  daFileName,
323	        agent_name: daStem,
324	      },
325	    };
326	  });
327	
328	  // Sort by number (files are already ordered, but be explicit)
329	  ledgerEntries.sort((a, b) => a.number - b.number);
330	
331	  // ---------------------------------------------------------------------------
332	  // Non-ledger suites (standalone, ledger-support)
333	  // ---------------------------------------------------------------------------
334	
335	  /**
336	   * Derives the role name for a non-ledger persona by stripping the known suite
337	   * suffix from the persona's `name` field.
338	   * e.g. "Developer (Standalone)"  → "Developer"
339	   *      "Ledger Bootstrapper"     → "Ledger Bootstrapper"  (no recognized suffix)
340	   */
341	  function deriveRole(name) {
342	    return name
343	      .replace(/\s+\(Standalone\)$/i, '')
344	      .replace(/\s+\(Ledger Support\)$/i, '')
345	      .trim();
346	  }
347	
348	  const nonLedgerEntries = [];
349	
350	  for (const [suiteName, suiteMetaDir] of NON_LEDGER_SUITES) {
351	    if (!fs.existsSync(suiteMetaDir)) continue;
352	
353	    const suiteFiles = fs.readdirSync(suiteMetaDir)
354	      .filter(f => f.endsWith('.yaml') && !f.startsWith('_'));
355	
356	    // Read suite-level _shared.yaml for default model slug (if present)
357	    const suiteSharedPath = path.join(suiteMetaDir, '_shared.yaml');
358	    let suiteDefaultModelSlug = undefined;
359	    if (fs.existsSync(suiteSharedPath)) {
360	      const suiteSharedData = parseYamlScalars(
361	        fs.readFileSync(suiteSharedPath, 'utf8'),
362	        ['default_model_slug'],
363	      );
364	      suiteDefaultModelSlug = suiteSharedData.default_model_slug || undefined;
365	    }
366	
367	    for (const file of suiteFiles) {
368	      const raw  = fs.readFileSync(path.join(suiteMetaDir, file), 'utf8');
369	      const data = parseYamlScalars(raw, STANDALONE_SCALAR_FIELDS);
370	
371	      if (!data.id) continue; // malformed YAML — skip silently
372	
373	      const ccFileName = data.cc_file_name;
374	      if (!ccFileName) continue; // no output target — skip
375	
376	      const daFileName = data.da_file_name || ccFileName;
377	      const ccStem     = stem(ccFileName);
378	      const daStem     = stem(daFileName);
379	      const version    = resolveVersionFromChangelog(raw) || data.version || DEFAULT_VERSION;
380	      const personaName = data.name || stem(file);
381	      const role        = deriveRole(personaName);
382	
383	      const modelInfo = resolveModel(
384	        data.id,
385	        data.model_slug || suiteDefaultModelSlug,
386	        undefined,  // no ledger-style shared model default for non-ledger suites
387	        undefined,
388	        uuidToSlug,
389	        assignments,
390	        registryEntries,
391	      );
392	
393	      const entry = {
394	        number:     null,
395	        id:         data.id,
396	        role,
397	        version,
398	        suite:      suiteName,
399	        model:      modelInfo.model,
400	        model_slug: modelInfo.model_slug,
401	        cc_model:   modelInfo.cc_model,
402	        vscode: {
403	          file_name:  data.vs_file_name || ccFileName,
404	          agent_name: personaName,
405	        },
406	        claude_code: {
407	          file_name:  ccFileName,
408	          agent_name: ccStem,
409	        },
410	        deep_agents: {
411	          file_name:  daFileName,
412	          agent_name: daStem,
413	        },
414	      };
415	
416	      nonLedgerEntries.push(entry);
417	    }
418	  }
419	
420	  // Sort non-ledger entries alphabetically by suite then role for stable output
421	  nonLedgerEntries.sort((a, b) => {
422	    if (a.suite !== b.suite) return a.suite < b.suite ? -1 : 1;
423	    return a.role < b.role ? -1 : 1;
424	  });
425	
426	  // ---------------------------------------------------------------------------
427	  // Write name-mapping.json — ledger entries first, then non-ledger suites
428	  // ---------------------------------------------------------------------------
429	
430	  const mapping = [...ledgerEntries, ...nonLedgerEntries];
431	
432	  fs.writeFileSync(outPath, JSON.stringify(mapping, null, 2) + '\n', 'utf8');
433	  console.log(`Generated personas/name-mapping.json with ${mapping.length} entries (${ledgerEntries.length} ledger, ${nonLedgerEntries.length} non-ledger).`);
434	}
435	
436	// Always: validate {{agent_slug_*}} cross-references (real builds AND --check).
437	// Ensures every {{agent_slug_X_Y}} reference in a persona content file has a
438	// matching slug "x-y" declared in that persona's `subagents` list in the YAML.
439	{
440	  const metaDir    = path.join(ROOT, 'personas', 'ledger', 'src', 'meta');
441	  const contentDir = path.join(ROOT, 'personas', 'ledger', 'src', 'content');
442	
443	  /**
444	   * Parse a flat dash-prefixed block list from YAML text under `key`.
445	   * Handles: key:\n  - item1\n  - item2
446	   * Returns [] when the key is absent, empty, or has an inline scalar value.
447	   */
448	  function extractSubagentsList(text, key) {
449	    const prefix = key + ':';
450	    let collecting = false;
451	    const result = [];
452	
453	    for (const line of text.split('\n')) {
454	      const stripped = line.trim();
455	      if (!stripped || stripped.startsWith('#')) continue;
456	
457	      if (stripped.startsWith(prefix)) {
458	        const rest = stripped.slice(prefix.length).trim();
459	        if (!rest) {
460	          collecting = true;
461	        }
462	        continue;
463	      }
464	
465	      if (collecting) {
466	        if (stripped.startsWith('- ')) {
467	          let val = stripped.slice(2).trim();
468	          if ((val.startsWith('"') && val.endsWith('"')) ||
469	              (val.startsWith("'") && val.endsWith("'"))) {
470	            val = val.slice(1, -1);
471	          }
472	          const ci = val.indexOf(' #');
473	          if (ci !== -1) val = val.slice(0, ci).trim();
474	          result.push(val);
475	        } else {
476	          break;  // next top-level key — stop collecting
477	        }
478	      }
479	    }
480	    return result;
481	  }
482	
483	  const metaFiles = fs.existsSync(metaDir)
484	    ? fs.readdirSync(metaDir).filter(f => /^\d+-/.test(f) && f.endsWith('.yaml'))
485	    : [];
486	
487	  const errors = [];
488	
489	  for (const yamlFile of metaFiles) {
490	    const baseName    = yamlFile.replace('.yaml', '');
491	    const contentPath = path.join(contentDir, baseName + '.md');
492	    if (!fs.existsSync(contentPath)) continue;
493	
494	    const subagents   = extractSubagentsList(
495	      fs.readFileSync(path.join(metaDir, yamlFile), 'utf8'),
496	      'subagents',
497	    );
498	    const contentText = fs.readFileSync(contentPath, 'utf8');
499	
500	    const agentSlugRe = /\{\{agent_slug_([a-z0-9_]+)\}\}/g;

501	    let m;
502	    while ((m = agentSlugRe.exec(contentText)) !== null) {
503	      const suffix       = m[1];
504	      const expectedSlug = suffix.replace(/_/g, '-');
505	
506	      if (!subagents.includes(expectedSlug)) {
507	        errors.push(
508	          `Persona "${baseName}": {{agent_slug_${suffix}}} references slug ` +
509	          `"${expectedSlug}" which is not declared in the subagents list. ` +
510	          `Add "${expectedSlug}" to the subagents field in ${yamlFile}.`,
511	        );
512	      }
513	    }
514	  }
515	
516	  if (errors.length > 0) {
517	    console.error('\n[ERROR] agent_slug cross-reference check failed:\n');
518	    for (const err of errors) {
519	      console.error('  ' + err);
520	    }
521	    process.exit(1);
522	  }
523	}

